//! S-320 done criterion: certificates generated by taky-pki `certgen` and by the ORIGINAL
//! `taky/util/anc.py` differ only in keys, serials and dates — compared via
//! `openssl x509 -text` and `openssl asn1parse` (string types, extension bytes, order).
//! Also: `openssl verify` for Rust-issued certificates, Rust issuing on a Python CA and
//! Python issuing on a Rust CA, key file format, and cert-db.txt lines.
//!
//! Needs `openssl` and a Python with `cryptography` (env `TAKY_PYREF_PYTHON`, else
//! `tools/pyref/.state/venv/bin/python`, else `python3`); otherwise the test is skipped with a
//! note on stderr. Python runs with `-I -B` (no `__pycache__` in `taky/`) and `TZ=UTC`.
#![cfg(feature = "gen")]
#![allow(clippy::expect_used)] // test helpers outside #[test] fns

use std::path::{Path, PathBuf};
use std::process::Command;

use taky_pki::CertDb;
use taky_pki::certgen::{self, CertAuthority, CertKind, KeyCert};

fn manifest() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

fn anc_py() -> PathBuf {
    manifest().join("../../../taky/taky/util/anc.py")
}

fn gen_script() -> PathBuf {
    manifest().join("tests/pyref/gen_certs.py")
}

fn find_python() -> Option<PathBuf> {
    let mut cands = Vec::new();
    if let Some(p) = std::env::var_os("TAKY_PYREF_PYTHON") {
        cands.push(PathBuf::from(p));
    }
    cands.push(manifest().join("../../tools/pyref/.state/venv/bin/python"));
    cands.push(PathBuf::from("python3"));
    cands.into_iter().find(|py| {
        Command::new(py)
            .args(["-I", "-B", "-c", "import cryptography"])
            .output()
            .is_ok_and(|o| o.status.success())
    })
}

fn have_openssl() -> bool {
    Command::new("openssl")
        .arg("version")
        .output()
        .is_ok_and(|o| o.status.success())
}

fn run(cmd: &mut Command) -> String {
    let out = cmd.output().expect("spawn");
    assert!(
        out.status.success(),
        "{cmd:?} failed: {}{}",
        String::from_utf8_lossy(&out.stdout),
        String::from_utf8_lossy(&out.stderr)
    );
    String::from_utf8(out.stdout).expect("utf8")
}

fn python(py: &Path, args: &[&Path]) {
    let mut c = Command::new(py);
    c.args(["-I", "-B", "-W", "ignore"])
        .arg(gen_script())
        .arg(anc_py())
        .args(args)
        .env("TZ", "UTC");
    run(&mut c);
}

fn is_hex_line(s: &str) -> bool {
    let s = s.trim().trim_start_matches("keyid:").trim_end_matches(':');
    !s.is_empty()
        && s.split(':')
            .all(|b| b.len() == 2 && b.chars().all(|c| c.is_ascii_hexdigit()))
}

/// `openssl x509 -text -noout` with serials, dates and key material (modulus, SKI/AKI,
/// signature value) replaced by placeholders.
fn x509_text(crt: &Path) -> String {
    let text = run(Command::new("openssl")
        .args(["x509", "-noout", "-text", "-in"])
        .arg(crt));
    let mut out: Vec<String> = Vec::new();
    for line in text.lines() {
        let indent = &line[..line.len() - line.trim_start().len()];
        let t = line.trim();
        let norm = if is_hex_line(t) {
            format!("{indent}<HEX>")
        } else if let Some(k) = ["Not Before:", "Not After :"]
            .iter()
            .find(|k| t.starts_with(**k))
        {
            format!("{indent}{k} <DATE>")
        } else if t.starts_with("Serial Number: ") {
            format!("{indent}Serial Number:")
        } else {
            line.trim_end().to_owned()
        };
        if norm.ends_with("<HEX>") && out.last() == Some(&norm) {
            continue; // multi-line hex block → one placeholder
        }
        out.push(norm);
    }
    out.join("\n")
}

/// `openssl asn1parse -i`: depth, type and value of every element, without offsets/lengths;
/// serial, times and key-derived octets (SKI/AKI) masked. Shows string types (UTF8String vs
/// PrintableString) and exact extension bytes, which `-text` hides.
fn asn1(crt: &Path) -> String {
    let text = run(Command::new("openssl")
        .args(["asn1parse", "-i", "-in"])
        .arg(crt));
    let mut out = Vec::new();
    let mut prev_obj = String::new();
    let mut integers = 0;
    for line in text.lines() {
        let Some(d) = line.find("d=") else { continue };
        let depth: String = line[d..].split_whitespace().next().unwrap_or("").to_owned();
        let rest = line
            .split_once("prim:")
            .or_else(|| line.split_once("cons:"));
        let body = rest.map(|(_, b)| b.trim()).unwrap_or("");
        let (ty, val) = match body.split_once(':') {
            Some((ty, val)) => (ty.trim().to_owned(), val.to_owned()),
            None => (body.to_owned(), String::new()),
        };
        let mut val = val;
        if ty == "INTEGER" {
            integers += 1;
            if integers == 2 {
                val = "<SERIAL>".into();
            }
        }
        if ty == "UTCTIME" || ty == "GENERALIZEDTIME" {
            val = "<DATE>".into();
        }
        if ty.starts_with("OCTET STRING")
            && (prev_obj.contains("Subject Key Identifier")
                || prev_obj.contains("Authority Key Identifier"))
        {
            val = "<KEYID>".into();
        }
        if ty == "OBJECT" {
            prev_obj = val.clone();
        }
        out.push(format!("{depth} {ty} {val}"));
    }
    out.join("\n")
}

fn verify(ca: &Path, crt: &Path) {
    let out = run(Command::new("openssl")
        .arg("verify")
        .arg("-CAfile")
        .arg(ca)
        .arg(crt));
    assert!(out.trim_end().ends_with(": OK"), "{out}");
}

fn assert_same(what: &str, py: &str, rs: &str) {
    if py != rs {
        let diff: Vec<String> = py
            .lines()
            .zip(rs.lines())
            .filter(|(a, b)| a != b)
            .map(|(a, b)| format!("  py: {a}\n  rs: {b}"))
            .collect();
        panic!(
            "{what}: Rust and Python differ ({} vs {} lines)\n{}\n--- python ---\n{py}\n--- rust ---\n{rs}",
            py.lines().count(),
            rs.lines().count(),
            diff.join("\n")
        );
    }
}

fn compare(py_crt: &Path, rs_crt: &Path) {
    let what = rs_crt.display().to_string();
    assert_same(&what, &x509_text(py_crt), &x509_text(rs_crt));
    assert_same(&what, &asn1(py_crt), &asn1(rs_crt));
}

fn write(dir: &Path, name: &str, kc: &KeyCert) -> PathBuf {
    let crt = dir.join(format!("{name}.crt"));
    certgen::write_certificate(&crt, &dir.join(format!("{name}.key")), kc).expect("write");
    crt
}

/// cert-db line with dates and serial masked; also checks the field formats.
fn db_shape(text: &str) -> String {
    text.lines()
        .map(|l| {
            let f: Vec<&str> = l.split('\t').collect();
            assert_eq!(f.len(), 5, "{l:?}");
            for d in &f[1..3] {
                assert_eq!(d.len(), 19, "naive isoformat without microseconds: {d}");
                assert!(chrono::NaiveDateTime::parse_from_str(d, "%Y-%m-%dT%H:%M:%S").is_ok());
            }
            assert_eq!(f[3].len(), 40);
            assert!(
                f[3].chars()
                    .all(|c| c.is_ascii_digit() || ('a'..='f').contains(&c))
            );
            format!("{}\t<D>\t<D>\t<SN>\t{}", f[0], f[4])
        })
        .collect::<Vec<_>>()
        .join("\n")
}

#[test]
fn rust_vs_python_certificates() {
    if !anc_py().exists() || !have_openssl() {
        eprintln!("SKIP pyref_x509: taky/taky/util/anc.py or openssl not available");
        return;
    }
    let Some(py) = find_python() else {
        eprintln!(
            "SKIP pyref_x509: no Python with `cryptography` (set TAKY_PYREF_PYTHON or run \
             tools/pyref/venv.sh)"
        );
        return;
    };
    let tmp = tempfile::tempdir().expect("tmp");
    let (pyd, rsd) = (tmp.path().join("py"), tmp.path().join("rs"));
    std::fs::create_dir_all(&pyd).expect("mkdir");
    std::fs::create_dir_all(&rsd).expect("mkdir");
    python(&py, &[Path::new("full"), &pyd]);

    // Rust: the same set (3 keys; srvip/srvlong reuse the server key — keygen is slow in debug)
    let now = chrono::Utc::now().naive_utc();
    let ca_kc = certgen::make_ca(now, certgen::CA_YEARS).expect("ca");
    let ca_crt = write(&rsd, "ca", &ca_kc);
    let ca = CertAuthority::load(&ca_crt, &rsd.join("ca.key")).expect("load ca");
    let srv_key = certgen::generate_key().expect("key");
    let issue = |host: &str, kind, key| {
        certgen::make_cert_with_key(&ca, host, now, certgen::CERT_YEARS, kind, key).expect(host)
    };
    let server = issue("taky.local", CertKind::Server, srv_key.clone());
    let srvip = issue("192.168.1.10", CertKind::Server, srv_key.clone());
    let srvlong = issue(&"h".repeat(64), CertKind::Server, srv_key);
    let client = certgen::make_cert(&ca, "JENNY", now, certgen::CERT_YEARS, CertKind::Client)
        .expect("client");
    let mut db = CertDb::open(&rsd.join("cert-db.txt")).expect("db");
    for (name, kc) in [
        ("server", &server),
        ("srvip", &srvip),
        ("srvlong", &srvlong),
        ("JENNY", &client),
    ] {
        let crt = write(&rsd, name, kc);
        compare(&pyd.join(format!("{name}.crt")), &crt);
        verify(&ca_crt, &crt);
    }
    compare(&pyd.join("ca.crt"), &ca_crt);
    verify(&ca_crt, &ca_crt);

    // The normalisation keeps the profile visible (not everything is masked) …
    let srv_text = x509_text(&rsd.join("server.crt"));
    eprintln!("normalised Rust server certificate:\n{srv_text}");
    for needle in [
        "Issuer: CN = CA, O = taky",
        "Subject: CN = taky.local",
        "Public-Key: (2048 bit)",
        "X509v3 Basic Constraints: critical",
        "X509v3 Key Usage: critical",
        "Digital Signature, Key Encipherment",
        "DNS:taky.local",
        "<HEX>",
        "Not After : <DATE>",
    ] {
        assert!(srv_text.contains(needle), "missing {needle:?}");
    }
    let cli_asn1 = asn1(&rsd.join("JENNY.crt"));
    eprintln!("normalised Rust client asn1parse:\n{cli_asn1}");
    assert!(cli_asn1.contains("d=5 UTF8STRING JENNY"));
    // … and profiles really differ after it (the comparison is not vacuous).
    assert_ne!(
        x509_text(&pyd.join("server.crt")),
        x509_text(&pyd.join("JENNY.crt"))
    );
    assert_ne!(asn1(&pyd.join("server.crt")), asn1(&pyd.join("srvip.crt")));
    db.add(&server.cert_der).expect("add server");
    db.add(&client.cert_der).expect("add client");

    // cert-db.txt: same lines up to dates/serials
    let py_db = std::fs::read_to_string(pyd.join("cert-db.txt")).expect("py db");
    let rs_db = std::fs::read_to_string(rsd.join("cert-db.txt")).expect("rs db");
    assert_eq!(db_shape(&py_db), db_shape(&rs_db));
    assert!(rs_db.ends_with('\n'));

    // key files: PKCS#1 PEM, 0600, valid; same `openssl pkey -text` header
    for d in [&pyd, &rsd] {
        let key = d.join("JENNY.key");
        let pem = std::fs::read_to_string(&key).expect("key");
        assert!(
            pem.starts_with("-----BEGIN RSA PRIVATE KEY-----\n"),
            "{}",
            key.display()
        );
        use std::os::unix::fs::PermissionsExt;
        let mode = std::fs::metadata(&key).expect("meta").permissions().mode();
        assert_eq!(mode & 0o777, 0o600, "{}", key.display());
        run(Command::new("openssl")
            .args(["rsa", "-check", "-noout", "-in"])
            .arg(&key));
    }
    let head = |d: &Path| {
        run(Command::new("openssl")
            .args(["pkey", "-noout", "-text", "-in"])
            .arg(d.join("JENNY.key")))
        .lines()
        .next()
        .unwrap_or_default()
        .to_owned()
    };
    assert_eq!(head(&pyd), head(&rsd));

    // Rust issues on the Python CA (PKCS#1 key written by Python)
    let pyca = CertAuthority::load(&pyd.join("ca.crt"), &pyd.join("ca.key")).expect("py ca");
    let x = certgen::make_cert_with_key(
        &pyca,
        "JENNY",
        now,
        certgen::CERT_YEARS,
        CertKind::Client,
        client.key.clone(),
    )
    .expect("rs on py ca");
    let x_crt = write(&tmp.path().join("rs"), "rs-on-pyca", &x);
    verify(&pyd.join("ca.crt"), &x_crt);
    compare(&pyd.join("JENNY.crt"), &x_crt);

    // Python issues on the Rust CA (anc.load_certificate reads our PKCS#1 key)
    let xd = tmp.path().join("py-on-rsca");
    std::fs::create_dir_all(&xd).expect("mkdir");
    python(
        &py,
        &[
            Path::new("issue"),
            &ca_crt,
            &rsd.join("ca.key"),
            &xd,
            Path::new("ALICE"),
            Path::new("client"),
        ],
    );
    verify(&ca_crt, &xd.join("ALICE.crt"));
}
